20: export class LocalValidator implements SlpValidator {
21:     BITBOX: BITBOX;
22:     cachedRawTransactions: { [txid: string]: string }
23:     cachedValidations: { [txid: string]: Validation }
24:     getRawTransactions: GetRawTransactionsAsync;
25:     slp: Slp;
26: 
27:     constructor(BITBOX: BITBOX, getRawTransactions: GetRawTransactionsAsync) {
28:         if(!BITBOX)
29:             throw Error("Must provide BITBOX instance to class constructor.")
30:         if(!getRawTransactions)
31:             throw Error("Must provide method getRawTransactions to class constructor.")
32:         this.BITBOX = BITBOX;
33:         this.getRawTransactions = getRawTransactions;
34:         this.slp = new Slp(BITBOX);
35:         this.cachedValidations = {};
36:         this.cachedRawTransactions = {};
37:     }
38: 
39:     addValidationFromStore(hex: string, isValid: boolean) {
40:         let id = (<Buffer>this.BITBOX.Crypto.sha256(this.BITBOX.Crypto.sha256(Buffer.from(hex, 'hex'))).reverse()).toString('hex');
41:         if(!this.cachedValidations[id])
42:             this.cachedValidations[id] = { hex: hex, validity: isValid, parents: [], details: null, invalidReason: null }
43:         if(!this.cachedRawTransactions[id])
44:             this.cachedRawTransactions[id] = hex;
45:     }
46:     
47:     async waitForCurrentValidationProcessing(txid: string) {
48:         // TODO: Add some timeout?
49:         let cached: Validation = this.cachedValidations[txid];
50: 
51:         while(true) {
52:             if(typeof cached.validity === 'boolean')
53:                 break
54:             await sleep(10);
55:         }
56:     }
57: 
58:     async waitForTransactionPreProcessing(txid: string){
59:         // TODO: Add some timeout?
60:         while(true) {
61:             if(this.cachedValidations[txid].hex && (this.cachedValidations[txid].details || typeof this.cachedValidations.validity === 'boolean'))
62:                 break
63:             await sleep(10);
64:         }
65:         //await sleep(100); // short wait to make sure parent's properties gets set first.
66:         return
67:     }
68: 
69:     async getRawTransaction(txid: string) {
70:         if(this.cachedRawTransactions[txid])
71:             return this.cachedRawTransactions[txid];
72:         this.cachedRawTransactions[txid] = (await this.getRawTransactions([txid]))[0]
73:         if(this.cachedRawTransactions[txid])
74:             return this.cachedRawTransactions[txid];
75:         return null;
76:     }
77: 
78:     async isValidSlpTxid(txid: string) {
79:         if(txid && !this.cachedValidations[txid]) {
80:             this.cachedValidations[txid] = { hex: null, validity: null, parents: [], details: null, invalidReason: null }
81:             this.cachedValidations[txid].hex = await this.getRawTransaction(txid);
82:         }
83: 
84:         // Check to see how we should proceed based on the validation-cache state
85:         if(!this.cachedValidations[txid].hex)
86:             await this.waitForTransactionPreProcessing(txid);
87:         if(typeof this.cachedValidations[txid].validity === 'boolean')
88:             return this.cachedValidations[txid].validity;
89:         if(this.cachedValidations[txid].details)
90:             await this.waitForCurrentValidationProcessing(txid);
91: 
92:         // Check SLP message validity
93:         let txn: BitcoreTransaction = new bitcore.Transaction(this.cachedValidations[txid].hex)
94:         let slpmsg: SlpTransactionDetails;
95:         try {
96:             slpmsg = this.cachedValidations[txid].details = this.slp.parseSlpOutputScript(txn.outputs[0]._scriptBuffer)
97:         } catch(e) {
98:             this.cachedValidations[txid].invalidReason = "SLP OP_RETURN parsing error (" + e.message + ")."
99:             return this.cachedValidations[txid].validity = false;
100:         }
101: 
102:         // Check DAG validity
103:         if(slpmsg.transactionType === SlpTransactionType.GENESIS) {
104:             return this.cachedValidations[txid].validity = true;
105:         } 
106:         else if (slpmsg.transactionType === SlpTransactionType.MINT) {
107:             for(let i = 0; i < txn.inputs.length; i++) {
108:                 let input_txid = txn.inputs[i].prevTxId.toString('hex')
109:                 let input_txhex = await this.getRawTransaction(input_txid)
110:                 if (input_txhex) {
111:                     let input_tx: BitcoreTransaction = new bitcore.Transaction(input_txhex);
112:                     try {
113:                         let input_slpmsg = this.slp.parseSlpOutputScript(input_tx.outputs[0]._scriptBuffer)
114:                         if(input_slpmsg.transactionType === SlpTransactionType.GENESIS)
115:                             input_slpmsg.tokenIdHex = input_txid;
116:                         if(input_slpmsg.tokenIdHex === slpmsg.tokenIdHex) {
117:                             if(input_slpmsg.transactionType === SlpTransactionType.GENESIS || input_slpmsg.transactionType === SlpTransactionType.MINT) {
118:                                 if(txn.inputs[i].outputIndex === input_slpmsg.batonVout)
119:                                     this.cachedValidations[txid].parents.push({ txid: txn.inputs[i].prevTxId.toString('hex'), versionType: input_slpmsg.versionType ,valid: null, inputQty: null })
120:                             }
121:                         }
122:                     } catch(_) {}
123:                 }
124:             }
125:             if(this.cachedValidations[txid].parents.length !== 1) {
126:                 this.cachedValidations[txid].invalidReason = "MINT transaction must have 1 valid baton parent."
127:                 return this.cachedValidations[txid].validity = false;
128:             }
129:         }
130:         else if(slpmsg.transactionType === SlpTransactionType.SEND) {
131:             let tokenOutQty = slpmsg.sendOutputs.reduce((t,v)=>{ return t.plus(v) }, new BigNumber(0))
132:             let tokenInQty = new BigNumber(0);
133:             for(let i = 0; i < txn.inputs.length; i++) {
134:                 let input_txid = txn.inputs[i].prevTxId.toString('hex')
135:                 let input_txhex = await this.getRawTransaction(input_txid)
136:                 if (input_txhex) {
137:                     let input_tx: BitcoreTransaction = new bitcore.Transaction(input_txhex);
138:                     try {
139:                         let input_slpmsg = this.slp.parseSlpOutputScript(input_tx.outputs[0]._scriptBuffer)
140:                         if(input_slpmsg.transactionType === SlpTransactionType.GENESIS)
141:                             input_slpmsg.tokenIdHex = input_txid;
142:                         if(input_slpmsg.tokenIdHex === slpmsg.tokenIdHex) {
143:                             if(input_slpmsg.transactionType === SlpTransactionType.SEND) {
144:                                 tokenInQty = tokenInQty.plus(input_slpmsg.sendOutputs[txn.inputs[i].outputIndex])
145:                                 this.cachedValidations[txid].parents.push({txid: txn.inputs[i].prevTxId.toString('hex'), versionType: input_slpmsg.versionType, valid: null, inputQty: input_slpmsg.sendOutputs[txn.inputs[i].outputIndex] })
146:                             }
147:                             else if(input_slpmsg.transactionType === SlpTransactionType.GENESIS || input_slpmsg.transactionType === SlpTransactionType.MINT) {
148:                                 if(txn.inputs[i].outputIndex === 1)
149:                                     tokenInQty = tokenInQty.plus(input_slpmsg.genesisOrMintQuantity)
150:                                     this.cachedValidations[txid].parents.push({txid: txn.inputs[i].prevTxId.toString('hex'), versionType: input_slpmsg.versionType, valid: null, inputQty: input_slpmsg.genesisOrMintQuantity })
151:                             }
152:                         }
153:                     } catch(_) {}
154:                 }
155:             }
156:             
157:             // Check token inputs are greater than token outputs (includes valid and invalid inputs)
158:             if(tokenOutQty.isGreaterThan(tokenInQty)) {
159:                 this.cachedValidations[txid].invalidReason = "Token outputs are greater than possible token inputs."
160:                 return this.cachedValidations[txid].validity = false;
161:             }
162:         }
163: 
164:         // Set validity validation-cache for parents, and handle MINT condition with no valid input
165:         let parentTxids = [...new Set(this.cachedValidations[txid].parents.map(p => p.txid))];
166:         for(let i = 0; i < parentTxids.length; i++) {
167:             let valid = await this.isValidSlpTxid(parentTxids[i])
168:             this.cachedValidations[txid].parents.filter(p => p.txid === parentTxids[i]).map(p => p.valid = valid);
169:             if(this.cachedValidations[txid].details.transactionType === SlpTransactionType.MINT && !valid) {
170:                 this.cachedValidations[txid].invalidReason = "MINT transaction with invalid baton parent."
171:                 return this.cachedValidations[txid].validity = false;
172:             }
173:         }
174: 
175:         // Check valid inputs are greater than token outputs
176:         if(this.cachedValidations[txid].details.transactionType === SlpTransactionType.SEND) {
177:             let validInputQty = this.cachedValidations[txid].parents.reduce((t, v) => { return v.valid ? t.plus(v.inputQty) : t }, new BigNumber(0));
178:             let tokenOutQty = slpmsg.sendOutputs.reduce((t,v)=>{ return t.plus(v) }, new BigNumber(0))
179:             if(tokenOutQty.isGreaterThan(validInputQty)) {
180:                 this.cachedValidations[txid].invalidReason = "Token outputs are greater than valid token inputs."
181:                 return this.cachedValidations[txid].validity = false;
182:             }
183:         }
184: 
185:         // Check versionType is not different from any valid parent
186:         if(this.cachedValidations[txid].parents.filter(p => p.valid).length > 0) {
187:             let validVersionType = this.cachedValidations[txid].parents.find(p => p.valid).versionType;
188:             if(this.cachedValidations[txid].details.versionType !== validVersionType) {
189:                 this.cachedValidations[txid].invalidReason = "SLP version/type mismatch from valid parent."
190:                 return this.cachedValidations[txid].validity = false;
191:             }
192:         } 
193:         // For case with 0 token SEND with no valid parents, must check GENESIS validity / versionType.
194:         else if(this.cachedValidations[txid].details.transactionType === SlpTransactionType.SEND) {
195:             let slpmsg = this.cachedValidations[txid].details
196:             let valid = await this.isValidSlpTxid(slpmsg.tokenIdHex);
197:             if(valid) {
198:                 let genesisTxn: BitcoreTransaction = new bitcore.Transaction(this.cachedValidations[slpmsg.tokenIdHex].hex)
199:                 let genesisMsg = this.slp.parseSlpOutputScript(genesisTxn.outputs[0]._scriptBuffer)
200:                 if(genesisMsg.versionType !== slpmsg.versionType) {
201:                     this.cachedValidations[txid].invalidReason = "SLP version/type mismatch from valid GENESIS."
202:                     return this.cachedValidations[txid].validity = false;
203:                 }
204:             } else {
205:                 this.cachedValidations[txid].invalidReason = "SEND has 0 outputs, but has invalid token GENESIS."
206:                 return this.cachedValidations[txid].validity = false;
207:             }
208:         }
209: 
210:         return this.cachedValidations[txid].validity = true;
211:     }
212: 
213:     async validateSlpTransactions(txids: string[]): Promise<string[]> {
214:         let res = [];
215:         for (let i = 0; i < txids.length; i++) {
216:             res.push((await this.isValidSlpTxid) ? txids[i] : '')
217:         }
218:         return res.filter((id: string) => id.length > 0);
219:     }
220: }

