27:     constructor(BITBOX: BITBOX, getRawTransactions: GetRawTransactionsAsync) {
28:         if(!BITBOX)
29:             throw Error("Must provide BITBOX instance to class constructor.")
30:         if(!getRawTransactions)
31:             throw Error("Must provide method getRawTransactions to class constructor.")
32:         this.BITBOX = BITBOX;
33:         this.getRawTransactions = getRawTransactions;
34:         this.slp = new Slp(BITBOX);
35:         this.cachedValidations = {};
36:         this.cachedRawTransactions = {};
37:     }
38: 
39:     addValidationFromStore(hex: string, isValid: boolean) {
40:         let id = (<Buffer>this.BITBOX.Crypto.sha256(this.BITBOX.Crypto.sha256(Buffer.from(hex, 'hex'))).reverse()).toString('hex');
41:         if(!this.cachedValidations[id])
42:             this.cachedValidations[id] = { hex: hex, validity: isValid, parents: [], details: null, invalidReason: null }
43:         if(!this.cachedRawTransactions[id])
44:             this.cachedRawTransactions[id] = hex;
