58:     async waitForTransactionPreProcessing(txid: string){
59:         // TODO: Add some timeout?
60:         while(true) {
61:             if(this.cachedValidations[txid].hex && (this.cachedValidations[txid].details || typeof this.cachedValidations.validity === 'boolean'))
62:                 break
