70:         if(this.cachedRawTransactions[txid])
71:             return this.cachedRawTransactions[txid];
72:         this.cachedRawTransactions[txid] = (await this.getRawTransactions([txid]))[0]
73:         if(this.cachedRawTransactions[txid])
