157:             // Check token inputs are greater than token outputs (includes valid and invalid inputs)
158:             if(tokenOutQty.isGreaterThan(tokenInQty)) {
159:                 this.cachedValidations[txid].invalidReason = "Token outputs are greater than possible token inputs."
160:                 return this.cachedValidations[txid].validity = false;
161:             }
162:         }
163: 
