47:     async waitForCurrentValidationProcessing(txid: string) {
48:         // TODO: Add some timeout?
49:         let cached: Validation = this.cachedValidations[txid];
50: 
51:         while(true) {
52:             if(typeof cached.validity === 'boolean')
53:                 break
54:             await sleep(10);
55:         }
56:     }
57: 
58:     async waitForTransactionPreProcessing(txid: string){
59:         // TODO: Add some timeout?
60:         while(true) {
61:             if(this.cachedValidations[txid].hex && (this.cachedValidations[txid].details || typeof this.cachedValidations.validity === 'boolean'))
62:                 break
