93:         let txn: BitcoreTransaction = new bitcore.Transaction(this.cachedValidations[txid].hex)
94:         let slpmsg: SlpTransactionDetails;
95:         try {
96:             slpmsg = this.cachedValidations[txid].details = this.slp.parseSlpOutputScript(txn.outputs[0]._scriptBuffer)
97:         } catch(e) {
98:             this.cachedValidations[txid].invalidReason = "SLP OP_RETURN parsing error (" + e.message + ")."
99:             return this.cachedValidations[txid].validity = false;
100:         }
101: 
102:         // Check DAG validity
103:         if(slpmsg.transactionType === SlpTransactionType.GENESIS) {
104:             return this.cachedValidations[txid].validity = true;
105:         } 
106:         else if (slpmsg.transactionType === SlpTransactionType.MINT) {
107:             for(let i = 0; i < txn.inputs.length; i++) {
108:                 let input_txid = txn.inputs[i].prevTxId.toString('hex')
